using DriveOS.Modules.Workforce.Domain.EmployeeDocuments;using DriveOS.SharedKernel.Identifiers;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DriveOS.Modules.Workforce.Infrastructure.Persistence.Configurations;
internal sealed class EmployeeDocumentConfiguration:IEntityTypeConfiguration<EmployeeDocument>{public void Configure(EntityTypeBuilder<EmployeeDocument>b){b.ToTable("employee_documents");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasConversion(x=>x.Value,x=>new EmployeeDocumentId(x)).ValueGeneratedNever();b.Property(x=>x.OrganizationId).HasConversion(x=>x.Value,x=>new OrganizationId(x));b.Property(x=>x.EmployeeId).HasConversion(x=>x.Value,x=>new EmployeeId(x));b.Property(x=>x.Category).HasConversion<int>();b.Property(x=>x.Confidentiality).HasConversion<int>();b.Property(x=>x.Status).HasConversion<int>();b.Property(x=>x.DocumentTypeCode).HasMaxLength(80);b.Property(x=>x.Title).HasMaxLength(256);b.Property(x=>x.Issuer).HasMaxLength(256);b.Property(x=>x.ReferenceNumber).HasMaxLength(128);b.Property(x=>x.RevocationReason).HasMaxLength(512);b.Property(x=>x.VerifiedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.SupersededByEmployeeDocumentId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new EmployeeDocumentId(x.Value):null);b.Property(x=>x.CreatedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.LastModifiedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.HasIndex(x=>new{x.OrganizationId,x.DocumentReferenceId}).IsUnique();b.HasIndex(x=>new{x.OrganizationId,x.EmployeeId,x.Status});b.HasIndex(x=>new{x.OrganizationId,x.EmployeeId,x.Category});b.HasIndex(x=>new{x.OrganizationId,x.ExpiresOn});}}
